```tsx
"use client";

import { useRef } from "react";
import { useGSAP } from "@gsap/react";
import { gsap, ScrollTrigger } from "@/lib/gsap";

export function ScrollProgress() {
  const barRef = useRef<HTMLDivElement>(null);

  useGSAP(() => {
    if (!barRef.current) return;

    const setProgress = gsap.quickSetter(barRef.current, "scaleX");

    const trigger = ScrollTrigger.create({
      start: 0,
      end: "max",
      onUpdate: ({ progress }) => {
        setProgress(progress);
      },
    });

    return () => trigger.kill();
  }, []);

  return (
    <div
      aria-hidden="true"
      className="pointer-events-none fixed inset-x-0 top-0 z-[100] h-1"
    >
      <div
        ref={barRef}
        className="h-full origin-left bg-current will-change-transform"
        style={{ transform: "scaleX(0)" }}
      />
    </div>
  );
}
```

Usa `scaleX` para evitar reflow, parte visualmente desde cero y limpia únicamente su propio `ScrollTrigger`. El import desde `@/lib/gsap` asume el registro SSR-safe centralizado exigido por el proyecto.
